{"command":"cat <<'EOF' > src/bytes_format.rs
use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BytesFormat {
    Plain,
    Metric,
    Binary,
}

impl BytesFormat {
    pub fn format_bytes(self, bytes: u64) -> String {
        match self {
            BytesFormat::Plain => bytes.to_string(),
            BytesFormat::Metric => format_unit(bytes, 1000.0, &["K", "M", "G", "T", "P"]),
            BytesFormat::Binary => format_unit(bytes, 1024.0, &["K", "M", "G", "T", "P"]),
        }
    }
}

fn format_unit(bytes: u64, base: f64, units: &[&str]) -> String {
    let bytes_f = bytes as f64;
    if bytes_f < base {
        return bytes.to_string();
    }
    let mut val = bytes_f / base;
    let mut unit_idx = 0;
    while val >= base && unit_idx + 1 < units.len() {
        val /= base;
        unit_idx += 1;
    }
    format!("{:.1}{}", val, units[unit_idx])
}
EOF"}

