{"command":"cat <<'EOF' > src/args.rs
use std::num::NonZeroUsize;
use std::path::PathBuf;
use clap::{Arg, ArgAction, Command};
use crate::bytes_format::BytesFormat;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Quantity {
    ApparentSize,
    BlockSize,
    BlockCount,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MaxDepth {
    Inf,
    Fixed(NonZeroUsize),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Threads {
    Auto,
    Max,
    Fixed(NonZeroUsize),
}

#[derive(Debug, Clone)]
pub struct AppArgs {
    pub files: Vec<PathBuf>,
    pub files_explicit: bool,
    pub json_input: bool,
    pub json_output: bool,
    pub bytes_format: BytesFormat,
    pub deduplicate_hardlinks: bool,
    pub top_down: bool,
    pub align_right: bool,
    pub quantity: Quantity,
    pub max_depth: MaxDepth,
    pub total_width: Option<usize>,
    pub column_width: Option<(usize, usize)>,
    pub min_ratio: f64,
    pub no_sort: bool,
    pub silent_errors: bool,
    pub progress: bool,
    pub threads: Threads,
    pub omit_json_shared_details: bool,
    pub omit_json_shared_summary: bool,
}

pub fn build_command() -> Command {
    Command::new("pdu")
        .version("0.21.1")
        .about("Summarize disk usage of the set of files, recursively for directories.")
        .after_help("Copyright: Apache-2.0 © 2021 Hoàng Văn Khải <https://github.com/KSXGitHub/>\nSponsor: https://github.com/sponsors/KSXGitHub")
        .arg(
            Arg::new("json-input")
                .long("json-input")
                .help("Read JSON data from stdin")
                .action(ArgAction::SetTrue)
                .conflicts_with_all(["quantity", "deduplicate-hardlinks", "silent-errors", "progress", "threads"]),
        )
        .arg(
            Arg::new("json-output")
                .long("json-output")
                .help("Print JSON data instead of an ASCII chart")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("bytes-format")
                .short('b')
                .long("bytes-format")
                .help("How to display the numbers of bytes")
                .value_name("BYTES_FORMAT")
                .value_parser(["plain", "metric", "binary"])
                .default_value("metric"),
        )
        .arg(
            Arg::new("deduplicate-hardlinks")
                .short('H')
                .long("deduplicate-hardlinks")
                .visible_aliases(["detect-links", "dedupe-links"])
                .help("Detect and subtract the sizes of hardlinks from their parent directory totals")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("top-down")
                .long("top-down")
                .help("Print the tree top-down instead of bottom-up")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("align-right")
                .long("align-right")
                .help("Set the root of the bars to the right")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("quantity")
                .short('q')
                .long("quantity")
                .help("Aspect of the files/directories to be measured")
                .value_name("QUANTITY")
                .value_parser(["apparent-size", "block-size", "block-count"])
                .default_value("block-size"),
        )
        .arg(
            Arg::new("max-depth")
                .short('d')
                .long("max-depth")
                .visible_alias("depth")
                .help("Maximum depth to display the data. Could be either \"inf\" or a positive integer")
                .value_name("MAX_DEPTH")
                .default_value("10"),
        )
        .arg(
            Arg::new("total-width")
                .short('w')
                .long("total-width")
                .visible_alias("width")
                .help("Width of the visualization")
                .value_name("TOTAL_WIDTH")
                .conflicts_with("column-width"),
        )
        .arg(
            Arg::new("column-width")
                .long("column-width")
                .help("Maximum widths of the tree column and width of the bar column")
                .value_names(["TREE_WIDTH", "BAR_WIDTH"])
                .number_of_values(2)
                .conflicts_with("total-width"),
        )
        .arg(
            Arg::new("min-ratio")
                .short('m')
                .long("min-ratio")
                .help("Minimal size proportion required to appear")
                .value_name("MIN_RATIO")
                .default_value("0.01"),
        )
        .arg(
            Arg::new("no-sort")
                .long("no-sort")
                .help("Do not sort the branches in the tree")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("silent-errors")
                .short('s')
                .long("silent-errors")
                .visible_alias("no-errors")
                .help("Prevent filesystem error messages from appearing in stderr")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("progress")
                .short('p')
                .long("progress")
                .help("Report progress being made at the expense of performance")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("threads")
                .long("threads")
                .help("Set the maximum number of threads to spawn. Could be either \"auto\", \"max\", or a positive integer")
                .value_name("THREADS")
                .default_value("auto"),
        )
        .arg(
            Arg::new("omit-json-shared-details")
                .long("omit-json-shared-details")
                .help("Do not output `.shared.details` in the JSON output")
                .action(ArgAction::SetTrue)
                .requires("json-output")
                .requires("deduplicate-hardlinks"),
        )
        .arg(
            Arg::new("omit-json-shared-summary")
                .long("omit-json-shared-summary")
                .help("Do not output `.shared.summary` in the JSON output")
                .action(ArgAction::SetTrue)
                .requires("json-output")
                .requires("deduplicate-hardlinks"),
        )
        .arg(
            Arg::new("FILES")
                .help("List of files and/or directories")
                .num_args(0..),
        )
}

pub fn parse_args() -> Result<AppArgs, clap::Error> {
    let matches = build_command().get_matches();

    let files_explicit = matches.contains_id("FILES") && matches.get_many::<String>("FILES").map_or(false, |m| m.count() > 0);
    let files: Vec<PathBuf> = matches
        .get_many::<String>("FILES")
        .map(|vals| vals.map(PathBuf::from).collect())
        .unwrap_or_else(|| vec![PathBuf::from(".")]);

    let json_input = matches.get_flag("json-input");
    let json_output = matches.get_flag("json-output");

    let bytes_format = match matches.get_one::<String>("bytes-format").map(|s| s.as_str()) {
        Some("plain") => BytesFormat::Plain,
        Some("binary") => BytesFormat::Binary,
        _ => BytesFormat::Metric,
    };

    let deduplicate_hardlinks = matches.get_flag("deduplicate-hardlinks");
    let top_down = matches.get_flag("top-down");
    let align_right = matches.get_flag("align-right");

    let quantity = match matches.get_one::<String>("quantity").map(|s| s.as_str()) {
        Some("apparent-size") => Quantity::ApparentSize,
        Some("block-count") => Quantity::BlockCount,
        _ => Quantity::BlockSize,
    };

    let max_depth_str = matches.get_one::<String>("max-depth").unwrap();
    let max_depth = parse_max_depth(max_depth_str).map_err(|msg| {
        build_command().error(
            clap::error::ErrorKind::InvalidValue,
            format!("invalid value '{max_depth_str}' for '--max-depth <MAX_DEPTH>': {msg}"),
        )
    })?;

    let total_width = matches
        .get_one::<String>("total-width")
        .map(|s| {
            s.parse::<usize>().map_err(|e| {
                build_command().error(
                    clap::error::ErrorKind::InvalidValue,
                    format!("invalid value '{s}' for '--total-width <TOTAL_WIDTH>': {e}"),
                )
            })
        })
        .transpose()?;

    let column_width = if let Some(mut vals) = matches.get_many::<String>("column-width") {
        let tree_s = vals.next().unwrap();
        let bar_s = vals.next().unwrap();
        let tree_w = tree_s.parse::<usize>().map_err(|e| {
            build_command().error(
                clap::error::ErrorKind::InvalidValue,
                format!("invalid value '{tree_s}' for '--column-width <TREE_WIDTH> <BAR_WIDTH>': {e}"),
            )
        })?;
        let bar_w = bar_s.parse::<usize>().map_err(|e| {
            build_command().error(
                clap::error::ErrorKind::InvalidValue,
                format!("invalid value '{bar_s}' for '--column-width <TREE_WIDTH> <BAR_WIDTH>': {e}"),
            )
        })?;
        Some((tree_w, bar_w))
    } else {
        None
    };

    let min_ratio_str = matches.get_one::<String>("min-ratio").unwrap();
    let min_ratio = min_ratio_str.parse::<f64>().map_err(|e| {
        build_command().error(
            clap::error::ErrorKind::InvalidValue,
            format!("invalid value '{min_ratio_str}' for '--min-ratio <MIN_RATIO>': {e}"),
        )
    })?;

    let no_sort = matches.get_flag("no-sort");
    let silent_errors = matches.get_flag("silent-errors");
    let progress = matches.get_flag("progress");

    let threads_str = matches.get_one::<String>("threads").unwrap();
    let threads = parse_threads(threads_str).map_err(|msg| {
        build_command().error(
            clap::error::ErrorKind::InvalidValue,
            format!("invalid value '{threads_str}' for '--threads <THREADS>': {msg}"),
        )
    })?;

    let omit_json_shared_details = matches.get_flag("omit-json-shared-details");
    let omit_json_shared_summary = matches.get_flag("omit-json-shared-summary");

    Ok(AppArgs {
        files,
        files_explicit,
        json_input,
        json_output,
        bytes_format,
        deduplicate_hardlinks,
        top_down,
        align_right,
        quantity,
        max_depth,
        total_width,
        column_width,
        min_ratio,
        no_sort,
        silent_errors,
        progress,
        threads,
        omit_json_shared_details,
        omit_json_shared_summary,
    })
}

fn parse_max_depth(s: &str) -> Result<MaxDepth, String> {
    if s == "inf" {
        Ok(MaxDepth::Inf)
    } else {
        match s.parse::<NonZeroUsize>() {
            Ok(val) => Ok(MaxDepth::Fixed(val)),
            Err(e) => Err(format!("Value is neither \"inf\" nor a positive integer: {e}")),
        }
    }
}

fn parse_threads(s: &str) -> Result<Threads, String> {
    if s == "auto" {
        Ok(Threads::Auto)
    } else if s == "max" {
        Ok(Threads::Max)
    } else {
        match s.parse::<NonZeroUsize>() {
            Ok(val) => Ok(Threads::Fixed(val)),
            Err(e) => Err(format!("Value is neither \"auto\", \"max\", nor a number: {e}")),
        }
    }
}
EOF"}

