        .arg(
            Arg::new("json-input")
                .long("json-input")
                .help("Read JSON data from stdin")
                .action(ArgAction::SetTrue)
                .conflicts_with_all(["quantity", "deduplicate-hardlinks", "silent-errors", "progress", "threads"]),
        )
        .arg(
            Arg::new("json-output")
                .long("json-output")
                .help("Print JSON data instead of an ASCII chart")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("bytes-format")
                .short('b')
                .long("bytes-format")
                .help("How to display the numbers of bytes")
                .value_name("BYTES_FORMAT")
                .value_parser(["plain", "metric", "binary"])
                .default_value("metric"),
        )
        .arg(
            Arg::new("deduplicate-hardlinks")
                .short('H')
                .long("deduplicate-hardlinks")
                .visible_aliases(["detect-links", "dedupe-links"])
                .help("Detect and subtract the sizes of hardlinks from their parent directory totals")
                .action(ArgAction::SetTrue),
