#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct InodeKey {
    pub dev: u64,
    pub ino: u64,
}

#[derive(Debug, Clone)]
pub struct HardlinkItem {
    pub ino: u64,
    pub size: u64,
    pub links: u64,
