        let key = InodeKey { dev, ino };
        let is_first = !self.map.contains_key(&key);
        let entry = self.map.entry(key).or_insert_with(|| HardlinkItem {
            ino,
            size,
            links,
            paths: LinkPathList::new(),
        });
        entry.paths.push(path);
        is_first
    }
}
