    pub fn new(name: impl Into<String>, size: u64, children: Vec<DataTree>) -> Self {
        Self {
            name: name.into(),
            size,
            children,
        }
    }

    pub fn to_json_node(&self) -> JsonNode {
        JsonNode {
            name: self.name.clone(),
            size: self.size,
            children: self.children.iter().map(|c| c.to_json_node()).collect(),
        }
    }

    pub fn from_json_node(node: JsonNode) -> Self {
        Self {
            name: node.name,
            size: node.size,
            children: node.children.into_iter().map(Self::from_json_node).collect(),
        }
    }
}
