        if root_size > 0 {
            self.children.retain(|child| {
                let ratio = child.size as f64 / root_size as f64;
                ratio >= min_ratio
            });
        }
        for child in &mut self.children {
            child.retain_by_min_ratio(root_size, min_ratio);
        }
    }

    pub fn limit_max_depth(&mut self, current_depth: usize, max_depth: usize) {
        if current_depth + 1 >= max_depth {
            self.children.clear();
        } else {
            for child in &mut self.children {
                child.limit_max_depth(current_depth + 1, max_depth);
            }
        }
    }
}
