use std::collections::{HashMap, HashSet};
use std::fs;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use crate::args::Quantity;
use crate::data_tree::DataTree;
use crate::hardlink::{HardlinkList, InodeKey};
use crate::reporter::ProgressAndErrorReporter;

pub struct TreeBuilder<'a> {
    pub quantity: Quantity,
    pub deduplicate_hardlinks: bool,
    pub reporter: &'a ProgressAndErrorReporter,
    pub hardlinks: HardlinkList,
}

impl<'a> TreeBuilder<'a> {
    pub fn new(quantity: Quantity, deduplicate_hardlinks: bool, reporter: &'a ProgressAndErrorReporter) -> Self {
        Self {
            quantity,
            deduplicate_hardlinks,
            reporter,
            hardlinks: HardlinkList::new(),
        }
    }

    pub fn build_root(&mut self, paths: &[PathBuf]) -> DataTree {
        if paths.len() == 1 {
            let path = &paths[0];
            let name = path.to_string_lossy().to_string();
            let (tree, _) = self.build_tree(path, name);
            tree
        } else {
            let mut children = Vec::new();
            let mut total_inodes: HashMap<InodeKey, u64> = HashMap::new();
            let mut non_dedup_total = 0;
            for path in paths {
                let name = path.to_string_lossy().to_string();
                let (child_tree, child_inodes) = self.build_tree(path, name);
                non_dedup_total += child_tree.size;
                total_inodes.extend(child_inodes);
                children.push(child_tree);
            }
            let total_size = if self.deduplicate_hardlinks {
                total_inodes.values().sum()
            } else {
                non_dedup_total
            };
            DataTree::new("(total)", total_size, children)
        }
    }

    fn get_meta_size(&self, meta: &fs::Metadata) -> u64 {
        match self.quantity {
            Quantity::ApparentSize => meta.len(),
            Quantity::BlockSize => meta.blocks() * 512,
            Quantity::BlockCount => meta.blocks(),
        }
    }

    fn build_tree(&mut self, path: &Path, name: String) -> (DataTree, HashMap<InodeKey, u64>) {
        self.reporter.update_progress();
        let path_str = path.to_string_lossy().to_string();

        let meta = match fs::symlink_metadata(path) {
            Ok(m) => m,
            Err(e) => {
                self.reporter.report_error("symlink_metadata", &path_str, &e);
                return (DataTree::new(name, 0, vec![]), HashMap::new());
            }
        };

        let meta_size = self.get_meta_size(&meta);
        let nlink = meta.nlink();
        let dev = meta.dev();
        let ino = meta.ino();
        let inode_key = InodeKey { dev, ino };

        if self.deduplicate_hardlinks && nlink > 1 {
            self.hardlinks.record(dev, ino, meta_size, nlink as u64, path.to_path_buf());
        }

        if meta.is_dir() {
            let entries = match fs::read_dir(path) {
                Ok(rd) => rd,
                Err(e) => {
                    self.reporter.report_error("read_dir", &path_str, &e);
                    let mut inodes = HashMap::new();
                    if self.deduplicate_hardlinks {
                        inodes.insert(inode_key, meta_size);
                    }
                    return (DataTree::new(name, meta_size, vec![]), inodes);
                }
            };

            let mut dir_entries = Vec::new();
            for entry_res in entries {
                match entry_res {
                    Ok(entry) => dir_entries.push(entry),
                    Err(e) => self.reporter.report_error("read_dir_entry", &path_str, &e),
                }
            }

            let mut children = Vec::new();
            let mut subtree_inodes: HashMap<InodeKey, u64> = HashMap::new();
            if self.deduplicate_hardlinks {
                subtree_inodes.insert(inode_key, meta_size);
            }

            for entry in dir_entries {
                let child_path = entry.path();
                let child_name = entry.file_name().to_string_lossy().to_string();
                let (child_tree, child_inodes) = self.build_tree(&child_path, child_name);

                subtree_inodes.extend(child_inodes);
                children.push(child_tree);
            }

            let dir_size = if self.deduplicate_hardlinks {
                subtree_inodes.values().sum()
            } else {
                meta_size + children.iter().map(|c| c.size).sum::<u64>()
            };

            (DataTree::new(name, dir_size, children), subtree_inodes)
        } else {
            let mut inode_map = HashMap::new();
            if self.deduplicate_hardlinks {
                inode_map.insert(inode_key, meta_size);
            }
            (DataTree::new(name, meta_size, vec![]), inode_map)
        }
    }
}
