{"command":"cat <<'EOF' > src/visualizer/methods.rs
use crate::args::Quantity;
use crate::bytes_format::BytesFormat;
use crate::data_tree::DataTree;

#[derive(Debug, Clone)]
pub struct FlattenedNode {
    pub name: String,
    pub size: u64,
    pub depth: usize,
    pub is_last_child_stack: Vec<bool>,
    pub is_first_child: bool,
    pub is_last_child: bool,
    pub has_children: bool,
    pub ancestor_sizes: Vec<u64>,
}

pub fn flatten_tree(
    tree: &DataTree,
    top_down: bool,
) -> Vec<FlattenedNode> {
    let mut nodes = Vec::new();
    flatten_recursive(
        tree,
        0,
        Vec::new(),
        true,
        true,
        Vec::new(),
        top_down,
        &mut nodes,
    );
    nodes
}

fn flatten_recursive(
    tree: &DataTree,
    depth: usize,
    is_last_child_stack: Vec<bool>,
    is_first_child: bool,
    is_last_child: bool,
    mut ancestor_sizes: Vec<u64>,
    top_down: bool,
    out: &mut Vec<FlattenedNode>,
) {
    ancestor_sizes.push(tree.size);

    let current = FlattenedNode {
        name: tree.name.clone(),
        size: tree.size,
        depth,
        is_last_child_stack: is_last_child_stack.clone(),
        is_first_child,
        is_last_child,
        has_children: !tree.children.is_empty(),
        ancestor_sizes: ancestor_sizes.clone(),
    };

    if top_down {
        out.push(current);
        let num_children = tree.children.len();
        for (i, child) in tree.children.iter().enumerate() {
            let mut next_stack = is_last_child_stack.clone();
            if depth > 0 {
                next_stack.push(is_last_child);
            }
            flatten_recursive(
                child,
                depth + 1,
                next_stack,
                i == 0,
                i + 1 == num_children,
                ancestor_sizes.clone(),
                top_down,
                out,
            );
        }
    } else {
        let num_children = tree.children.len();
        for (i, child) in tree.children.iter().enumerate() {
            let mut next_stack = is_last_child_stack.clone();
            if depth > 0 {
                next_stack.push(is_last_child);
            }
            flatten_recursive(
                child,
                depth + 1,
                next_stack,
                i == 0,
                i + 1 == num_children,
                ancestor_sizes.clone(),
                top_down,
                out,
            );
        }
        out.push(current);
    }
}

pub fn render_tree(
    nodes: &[FlattenedNode],
    root_size: u64,
    bytes_format: BytesFormat,
    quantity: Quantity,
    top_down: bool,
    align_right: bool,
    total_width: Option<usize>,
    column_width: Option<(usize, usize)>,
) -> String {
    if nodes.is_empty() {
        return String::new();
    }

    // Format size strings
    let size_strs: Vec<String> = nodes
        .iter()
