                print_custom_error(&format!("DeserializationFailure: {}", e));
                process::exit(3);
            }
        };

        if json_data.schema_version != "2024-11-02" {
            print_custom_error(&format!(
                "DeserializationFailure: InvalidSchema: \"{}\": input schema is not \"2024-11-02\"",
                json_data.schema_version
            ));
            process::exit(3);
        }

        let data_tree = DataTree::from_json_node(json_data.tree);
        (data_tree, json_data.unit, None)
    } else {
        let reporter = ProgressAndErrorReporter::new(args.silent_errors, args.progress);
        let mut builder = TreeBuilder::new(args.quantity, args.deduplicate_hardlinks, &reporter);
        let data_tree = builder.build_root(&args.files);
        reporter.finish();

        let unit = match args.quantity {
            Quantity::BlockCount => Unit::Blocks,
            _ => Unit::Bytes,
        };

        (data_tree, unit, Some(builder.hardlinks))
    };

    let root_size = tree.size;

    // Apply sorting
    if !args.no_sort {
        tree.sort_children_descending();
    }

    // Apply min-ratio filtering
    tree.retain_by_min_ratio(root_size, args.min_ratio);

    // Apply max-depth limit
    if let MaxDepth::Fixed(d) = args.max_depth {
        tree.limit_max_depth(0, d.get());
    }

    if args.json_output {
        let shared = if args.deduplicate_hardlinks {
            if let Some(hl) = hardlinks_opt {
                let mut details = Vec::new();
                let mut exclusive_inodes = 0;
                let mut all_links = 0;
                let mut detected_links = 0;
                let mut exclusive_links = 0;
                let mut shared_size = 0;
                let mut exclusive_shared_size = 0;

                for item in hl.map.values() {
                    let det_links = item.paths.paths.len() as u64;
                    let is_exclusive = det_links == item.links;

                    if is_exclusive {
                        exclusive_inodes += 1;
                        exclusive_links += det_links;
                        exclusive_shared_size += item.size;
                    }

                    all_links += item.links;
                    detected_links += det_links;
                    shared_size += item.size;

                    let mut paths_strs: Vec<String> = item
                        .paths
                        .paths
                        .iter()
                        .map(|p| p.to_string_lossy().to_string())
                        .collect();

                    details.push(JsonSharedDetail {
                        ino: item.ino,
                        size: item.size,
                        links: item.links,
                        paths: paths_strs,
                    });
                }

                details.sort_by_key(|d| d.ino);

                let summary = JsonSharedSummary {
                    inodes: hl.map.len(),
                    exclusive_inodes,
                    all_links,
                    detected_links,
                    exclusive_links,
                    shared_size,
                    exclusive_shared_size,
                };

                let opt_details = if args.omit_json_shared_details { None } else { Some(details) };
                let opt_summary = if args.omit_json_shared_summary { None } else { Some(summary) };

                if opt_details.is_none() && opt_summary.is_none() {
                    None
                } else {
                    Some(JsonShared {
                        details: opt_details,
                        summary: opt_summary,
                    })
                }
            } else {
                None
            }
        } else {
            None
        };

        let json_out = JsonData {
            schema_version: "2024-11-02".to_string(),
            pdu: Some("0.21.1".to_string()),
            unit,
            tree: tree.to_json_node(),
            shared,
        };

        match serde_json::to_string(&json_out) {
            Ok(s) => print!("{}", s),
            Err(e) => {
                print_custom_error(&format!("{}", e));
                process::exit(1);
            }
        }
    } else {
        let flattened = flatten_tree(&tree, args.top_down);
        let chart = render_tree(
            &flattened,
            root_size,
            args.bytes_format,
            args.quantity,
            args.top_down,
            args.align_right,
            args.total_width,
            args.column_width,
        );
        print!("{}", chart);
    }
}
