        .arg(
            Arg::new("no-sort")
                .long("no-sort")
                .help("Do not sort the branches in the tree")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("silent-errors")
                .short('s')
                .long("silent-errors")
                .visible_alias("no-errors")
                .help("Prevent filesystem error messages from appearing in stderr")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("progress")
                .short('p')
                .long("progress")
                .help("Report progress being made at the expense of performance")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("threads")
                .long("threads")
                .help("Set the maximum number of threads to spawn. Could be either \"auto\", \"max\", or a positive integer")
                .value_name("THREADS")
                .default_value("auto"),
        )
        .arg(
            Arg::new("omit-json-shared-details")
                .long("omit-json-shared-details")
                .help("Do not output `.shared.details` in the JSON output")
                .action(ArgAction::SetTrue)
                .requires("json-output")
                .requires("deduplicate-hardlinks"),
        )
        .arg(
            Arg::new("omit-json-shared-summary")
                .long("omit-json-shared-summary")
                .help("Do not output `.shared.summary` in the JSON output")
                .action(ArgAction::SetTrue)
                .requires("json-output")
                .requires("deduplicate-hardlinks"),
        )
        .arg(
            Arg::new("FILES")
                .help("List of files and/or directories")
                .num_args(0..),
        )
}

pub fn parse_args() -> Result<AppArgs, clap::Error> {
    let matches = build_command().get_matches();

    let files_explicit = matches.contains_id("FILES") && matches.get_many::<String>("FILES").map_or(false, |m| m.count() > 0);
    let files: Vec<PathBuf> = matches
        .get_many::<String>("FILES")
        .map(|vals| vals.map(PathBuf::from).collect())
        .unwrap_or_else(|| vec![PathBuf::from(".")]);

    let json_input = matches.get_flag("json-input");
    let json_output = matches.get_flag("json-output");

    let bytes_format = match matches.get_one::<String>("bytes-format").map(|s| s.as_str()) {
        Some("plain") => BytesFormat::Plain,
        Some("binary") => BytesFormat::Binary,
        _ => BytesFormat::Metric,
    };

    let deduplicate_hardlinks = matches.get_flag("deduplicate-hardlinks");
    let top_down = matches.get_flag("top-down");
    let align_right = matches.get_flag("align-right");

    let quantity = match matches.get_one::<String>("quantity").map(|s| s.as_str()) {
        Some("apparent-size") => Quantity::ApparentSize,
        Some("block-count") => Quantity::BlockCount,
        _ => Quantity::BlockSize,
    };

    let max_depth_str = matches.get_one::<String>("max-depth").unwrap();
    let max_depth = parse_max_depth(max_depth_str).map_err(|msg| {
        build_command().error(
            clap::error::ErrorKind::InvalidValue,
            format!("invalid value '{max_depth_str}' for '--max-depth <MAX_DEPTH>': {msg}"),
        )
    })?;

    let total_width = matches
        .get_one::<String>("total-width")
        .map(|s| {
            s.parse::<usize>().map_err(|e| {
                build_command().error(
                    clap::error::ErrorKind::InvalidValue,
                    format!("invalid value '{s}' for '--total-width <TOTAL_WIDTH>': {e}"),
                )
            })
        })
        .transpose()?;

    let column_width = if let Some(mut vals) = matches.get_many::<String>("column-width") {
        let tree_s = vals.next().unwrap();
        let bar_s = vals.next().unwrap();
        let tree_w = tree_s.parse::<usize>().map_err(|e| {
            build_command().error(
                clap::error::ErrorKind::InvalidValue,
                format!("invalid value '{tree_s}' for '--column-width <TREE_WIDTH> <BAR_WIDTH>': {e}"),
            )
        })?;
        let bar_w = bar_s.parse::<usize>().map_err(|e| {
            build_command().error(
                clap::error::ErrorKind::InvalidValue,
                format!("invalid value '{bar_s}' for '--column-width <TREE_WIDTH> <BAR_WIDTH>': {e}"),
            )
        })?;
        Some((tree_w, bar_w))
    } else {
        None
    };

    let min_ratio_str = matches.get_one::<String>("min-ratio").unwrap();
    let min_ratio = min_ratio_str.parse::<f64>().map_err(|e| {
        build_command().error(
            clap::error::ErrorKind::InvalidValue,
            format!("invalid value '{min_ratio_str}' for '--min-ratio <MIN_RATIO>': {e}"),
        )
    })?;

    let no_sort = matches.get_flag("no-sort");
    let silent_errors = matches.get_flag("silent-errors");
    let progress = matches.get_flag("progress");

    let threads_str = matches.get_one::<String>("threads").unwrap();
    let threads = parse_threads(threads_str).map_err(|msg| {
        build_command().error(
            clap::error::ErrorKind::InvalidValue,
            format!("invalid value '{threads_str}' for '--threads <THREADS>': {msg}"),
        )
    })?;

    let omit_json_shared_details = matches.get_flag("omit-json-shared-details");
    let omit_json_shared_summary = matches.get_flag("omit-json-shared-summary");

    Ok(AppArgs {
        files,
        files_explicit,
        json_input,
        json_output,
        bytes_format,
        deduplicate_hardlinks,
        top_down,
        align_right,
        quantity,
        max_depth,
        total_width,
        column_width,
        min_ratio,
        no_sort,
        silent_errors,
        progress,
        threads,
        omit_json_shared_details,
        omit_json_shared_summary,
    })
}

fn parse_max_depth(s: &str) -> Result<MaxDepth, String> {
    if s == "inf" {
        Ok(MaxDepth::Inf)
    } else {
        match s.parse::<NonZeroUsize>() {
            Ok(val) => Ok(MaxDepth::Fixed(val)),
            Err(e) => Err(format!("Value is neither \"inf\" nor a positive integer: {e}")),
        }
    }
}

fn parse_threads(s: &str) -> Result<Threads, String> {
    if s == "auto" {
        Ok(Threads::Auto)
    } else if s == "max" {
        Ok(Threads::Max)
    } else {
        match s.parse::<NonZeroUsize>() {
            Ok(val) => Ok(Threads::Fixed(val)),
            Err(e) => Err(format!("Value is neither \"auto\", \"max\", nor a number: {e}")),
        }
    }
}
EOF"}

