        .collect();

    let max_size_len = size_strs.iter().map(|s| s.len()).max().unwrap_or(0);

    let raw_tree_strs: Vec<String> = nodes
        .iter()
        .map(|node| {
            let mut prefix = String::new();
            for &has_line in &node.is_last_child_stack {
                if has_line {
                    prefix.push_str("│ ");
                } else {
                    prefix.push_str("  ");
                }
            }

            let connector = if top_down {
                if node.depth == 0 {
                    "└─┬"
                } else if node.has_children {
                    if node.is_last_child { "└─┬" } else { "├─┬" }
                } else {
                    if node.is_last_child { "└──" } else { "├──" }
                }
            } else {
                if node.depth == 0 {
                    "┌─┴"
                } else if node.has_children {
                    if node.is_first_child { "┌─┴" } else { "├─┴" }
                } else {
                    if node.is_first_child { "┌──" } else { "├──" }
                }
            };

            format!("{}{}{}", prefix, connector, node.name)
        })
        .collect();

    let unconstrained_tree_width = raw_tree_strs.iter().map(|s| s.chars().count()).max().unwrap_or(0);

    let default_width = if let Ok((cols, _)) = crossterm::terminal::size() {
        cols as usize
    } else {
        150
    };

    let (tree_width, bar_width) = if let Some((tw, bw)) = column_width {
        let actual_tw = unconstrained_tree_width.min(tw);
        (actual_tw, bw)
    } else {
        let tw = total_width.unwrap_or(default_width);
        let fixed_overhead = max_size_len + 1 + 1 + 1 + 4;
        if tw >= max_size_len + 1 + unconstrained_tree_width + 1 + 4 + 1 + 4 {
            let bw = tw.saturating_sub(max_size_len + 1 + unconstrained_tree_width + 6);
            (unconstrained_tree_width, bw)
        } else {
            let bw = 4;
            let tw_tree = tw.saturating_sub(fixed_overhead + bw);
            (tw_tree, bw)
        }
    };

    let mut lines = Vec::new();

    for (i, node) in nodes.iter().enumerate() {
        let size_str = format!("{:>width$}", size_strs[i], width = max_size_len);

        let mut prefix = String::new();
        for &has_line in &node.is_last_child_stack {
            if has_line {
                prefix.push_str("│ ");
            } else {
                prefix.push_str("  ");
            }
        }

        let connector = if top_down {
            if node.depth == 0 {
                "└─┬"
            } else if node.has_children {
                if node.is_last_child { "└─┬" } else { "├─┬" }
            } else {
                if node.is_last_child { "└──" } else { "├──" }
            }
        } else {
            if node.depth == 0 {
                "┌─┴"
            } else if node.has_children {
                if node.is_first_child { "┌─┴" } else { "├─┴" }
            } else {
                if node.is_first_child { "┌──" } else { "├──" }
            }
        };

        let prefix_conn_len = prefix.chars().count() + connector.chars().count();
        let name = &node.name;

        let tree_col = if prefix_conn_len >= tree_width {
            let full = format!("{}{}", prefix, connector);
            full.chars().take(tree_width).collect::<String>()
        } else {
            let available_for_name = tree_width - prefix_conn_len;
            let name_chars = name.chars().count();
            let truncated_name = if name_chars <= available_for_name {
                name.clone()
            } else if available_for_name >= 3 {
                let take = available_for_name - 3;
                format!("{}...", name.chars().take(take).collect::<String>())
            } else {
                ".".repeat(available_for_name)
            };
            let formatted = format!("{}{}{}", prefix, connector, truncated_name);
            let formatted_len = formatted.chars().count();
            if formatted_len < tree_width {
                format!("{}{}", formatted, " ".repeat(tree_width - formatted_len))
            } else {
                formatted
            }
        };

        let bar_col = render_bar(&node.ancestor_sizes, root_size, bar_width, align_right);

        let pct = if root_size == 0 {
            0
        } else {
            ((node.size as f64 / root_size as f64) * 100.0).round() as u64
        };
        let pct_col = format!("{:>3}%", pct);

        lines.push(format!("{} {}│{}│{}", size_str, tree_col, bar_col, pct_col));
    }

    lines.join("\n") + "\n"
}

fn render_bar(ancestor_sizes: &[u64], root_size: u64, bar_width: usize, align_right: bool) -> String {
    if bar_width == 0 {
        return String::new();
    }

    let shades = ['█', '▓', '▒', '░'];
    let mut counts = Vec::new();

    // Only take ancestors up to root_size
    for &sz in ancestor_sizes {
        let cnt = if root_size == 0 {
            0
        } else {
            ((sz as f64 / root_size as f64) * bar_width as f64).round() as usize
        }.min(bar_width);
        counts.push(cnt);
    }

    let mut segment_counts = Vec::new();
    let mut prev = 0;
    for &cnt in &counts {
        let inc = cnt.saturating_sub(prev);
        segment_counts.push(inc);
        prev = cnt.max(prev);
    }

    let mut bar_chars = Vec::new();
    for (i, &cnt) in segment_counts.iter().enumerate() {
        if i + 1 == ancestor_sizes.len() {
            // Root extra size -> spaces
            break;
        }
        let shade = shades[i.min(shades.len() - 1)];
        for _ in 0..cnt {
            bar_chars.push(shade);
        }
    }

    while bar_chars.len() < bar_width {
        bar_chars.push(' ');
    }
    bar_chars.truncate(bar_width);

    if align_right {
        bar_chars.reverse();
    }

    bar_chars.into_iter().collect()
}
EOF"}

{"command":"cat <<'EOF' > src/app/hdd.rs
use std::io::{self, Read};
use std::process;

use crate::args::{AppArgs, MaxDepth, Quantity};
use crate::data_tree::DataTree;
use crate::json_data::{JsonData, JsonShared, JsonSharedDetail, JsonSharedSummary, Unit};
use crate::reporter::{print_custom_error, ProgressAndErrorReporter};
use crate::tree_builder::TreeBuilder;
use crate::visualizer::{flatten_tree, render_tree};

pub fn run(args: AppArgs) {
    crate::app::overlapping_arguments::validate_args(&args);

    let (mut tree, unit, hardlinks_opt) = if args.json_input {
        let mut input_str = String::new();
        if let Err(e) = io::stdin().read_to_string(&mut input_str) {
            print_custom_error(&format!("DeserializationFailure: {}", e));
            process::exit(3);
        }

        let json_data: JsonData = match serde_json::from_str(&input_str) {
            Ok(data) => data,
            Err(e) => {
                print_custom_error(&format!("DeserializationFailure: {}", e));
                process::exit(3);
            }
        };

        if json_data.schema_version != "2024-11-02" {
            print_custom_error(&format!(
                "DeserializationFailure: InvalidSchema: \"{}\": input schema is not \"2024-11-02\"",
                json_data.schema_version
            ));
            process::exit(3);
        }

        let data_tree = DataTree::from_json_node(json_data.tree);
        (data_tree, json_data.unit, None)
    } else {
        let reporter = ProgressAndErrorReporter::new(args.silent_errors, args.progress);
        let mut builder = TreeBuilder::new(args.quantity, args.deduplicate_hardlinks, &reporter);
        let data_tree = builder.build_root(&args.files);
        reporter.finish();

        let unit = match args.quantity {
            Quantity::BlockCount => Unit::Blocks,
            _ => Unit::Bytes,
        };

        (data_tree, unit, Some(builder.hardlinks))
    };

    let root_size = tree.size;

    if !args.no_sort {
        tree.sort_children_descending();
    }

    tree.retain_by_min_ratio(root_size, args.min_ratio);

    if let MaxDepth::Fixed(d) = args.max_depth {
        tree.limit_max_depth(0, d.get());
    }

    if args.json_output {
        let shared = if args.deduplicate_hardlinks {
            if let Some(hl) = hardlinks_opt {
                let mut details = Vec::new();
                let mut exclusive_inodes = 0;
                let mut all_links = 0;
                let mut detected_links = 0;
                let mut exclusive_links = 0;
                let mut shared_size = 0;
                let mut exclusive_shared_size = 0;

                for item in hl.map.values() {
                    let det_links = item.paths.paths.len() as u64;
                    let is_exclusive = det_links == item.links;

                    if is_exclusive {
                        exclusive_inodes += 1;
                        exclusive_links += det_links;
                        exclusive_shared_size += item.size;
                    }

                    all_links += item.links;
                    detected_links += det_links;
                    shared_size += item.size;

                    let paths_strs: Vec<String> = item
                        .paths
                        .paths
                        .iter()
                        .map(|p| p.to_string_lossy().to_string())
                        .collect();

                    details.push(JsonSharedDetail {
                        ino: item.ino,
                        size: item.size,
                        links: item.links,
                        paths: paths_strs,
                    });
                }

                details.sort_by_key(|d| d.ino);

                let summary = JsonSharedSummary {
                    inodes: hl.map.len(),
                    exclusive_inodes,
                    all_links,
                    detected_links,
                    exclusive_links,
                    shared_size,
                    exclusive_shared_size,
                };

                let opt_details = if args.omit_json_shared_details { None } else { Some(details) };
                let opt_summary = if args.omit_json_shared_summary { None } else { Some(summary) };

                if opt_details.is_none() && opt_summary.is_none() {
                    None
                } else {
                    Some(JsonShared {
                        details: opt_details,
                        summary: opt_summary,
                    })
                }
            } else {
                None
            }
        } else {
            None
        };

        let json_out = JsonData {
            schema_version: "2024-11-02".to_string(),
            pdu: Some("0.21.1".to_string()),
            unit,
            tree: tree.to_json_node(),
            shared,
        };

        match serde_json::to_string(&json_out) {
            Ok(s) => print!("{}", s),
            Err(e) => {
                print_custom_error(&format!("{}", e));
                process::exit(1);
            }
        }
    } else {
        let flattened = flatten_tree(&tree, args.top_down);
        let chart = render_tree(
            &flattened,
            root_size,
            args.bytes_format,
            args.quantity,
            args.top_down,
            args.align_right,
            args.total_width,
            args.column_width,
        );
        print!("{}", chart);

        if args.deduplicate_hardlinks {
            if let Some(hl) = hardlinks_opt {
                if !hl.map.is_empty() {
                    let mut exclusive_inodes = 0;
                    let mut all_links = 0;
                    let mut shared_size = 0;

                    for item in hl.map.values() {
                        let det_links = item.paths.paths.len() as u64;
                        if det_links == item.links {
                            exclusive_inodes += 1;
                        }
                        all_links += item.links;
                        shared_size += item.size;
                    }

                    let has_outside = exclusive_inodes < hl.map.len();
                    let formatted_size = match args.quantity {
                        Quantity::BlockCount => shared_size.to_string(),
                        _ => args.bytes_format.format_bytes(shared_size),
                    };

                    if has_outside {
                        println!("Hardlinks detected! Files have links outside this tree");
                    } else {
                        println!("Hardlinks detected! No files have links outside this tree");
                    }
                    println!("* Number of shared inodes: {}", hl.map.len());
                    println!("* Total number of links: {}", all_links);
                    println!("* Total shared size: {}", formatted_size);
                }
            }
        }
    }
}
EOF"}

