    depth: usize,
    open_levels: Vec<bool>,
    parent_ancestors: Vec<u64>,
    out: &mut Vec<FlattenedNode>,
) {
    let mut ancestor_sizes = vec![tree.size];
    ancestor_sizes.extend(parent_ancestors.iter().cloned());

    let num_children = tree.children.len();

    for (i, child) in tree.children.iter().rev().enumerate() {
        let is_first = i == 0;
        let is_last = i + 1 == num_children;

        let child_has_children = !child.children.is_empty();

        let mut child_open_levels = open_levels.clone();
        child_open_levels.push(!is_last);

        let connector = if is_first {
            if child_has_children { "┌─┴" } else { "┌──" }
        } else {
            if child_has_children { "├─┴" } else { "├──" }
        };

        let mut prefix = String::new();
        for k in 0..depth {
            if k < open_levels.len() && open_levels[k] {
                prefix.push_str("│ ");
            } else {
                prefix.push_str("  ");
            }
        }
        if depth > 0 {
            prefix.push_str("  ");
        }

        let mut child_ancestors = vec![child.size];
        child_ancestors.extend(ancestor_sizes.iter().cloned());

        if child_has_children {
            flatten_bottom_up(
                child,
                depth + 1,
                child_open_levels,
                ancestor_sizes.clone(),
                out,
            );
        } else {
            out.push(FlattenedNode {
                name: child.name.clone(),
                size: child.size,
                prefix,
                connector,
                ancestor_sizes: child_ancestors,
            });
        }
    }

    let mut prefix = String::new();
    for k in 0..depth.saturating_sub(1) {
        if k < open_levels.len() && open_levels[k] {
            prefix.push_str("│ ");
        } else {
            prefix.push_str("  ");
        }
    }
    if depth > 0 {
        prefix.push_str("  ");
    }

    let connector = if depth == 0 {
        "┌─┴"
    } else {
        "├─┴"
    };

    out.push(FlattenedNode {
        name: tree.name.clone(),
        size: tree.size,
        prefix,
        connector,
        ancestor_sizes,
    });
}

pub fn render_tree(
    nodes: &[FlattenedNode],
    root_size: u64,
    bytes_format: BytesFormat,
    quantity: Quantity,
    _top_down: bool,
    align_right: bool,
    total_width: Option<usize>,
    column_width: Option<(usize, usize)>,
) -> String {
    if nodes.is_empty() {
        return String::new();
    }

    let size_strs: Vec<String> = nodes
        .iter()
        .map(|node| match quantity {
            Quantity::BlockCount => node.size.to_string(),
            _ => bytes_format.format_bytes(node.size),
        })
        .collect();

    let max_size_len = size_strs.iter().map(|s| s.len()).max().unwrap_or(0);

    let raw_tree_strs: Vec<String> = nodes
        .iter()
        .map(|node| format!("{}{}{}", node.prefix, node.connector, node.name))
        .collect();

    let unconstrained_tree_width = raw_tree_strs.iter().map(|s| s.chars().count()).max().unwrap_or(0);

    let default_width = if let Ok((cols, _)) = crossterm::terminal::size() {
        cols as usize
    } else {
        150
    };

    let (tree_width, bar_width) = if let Some((tw, bw)) = column_width {
        let actual_tw = unconstrained_tree_width.min(tw);
        (actual_tw, bw)
    } else {
        let tw = total_width.unwrap_or(default_width);
        let fixed_overhead = max_size_len + 1 + 1 + 1 + 4;
        if tw >= max_size_len + 1 + unconstrained_tree_width + 1 + 4 + 1 + 4 {
            let bw = tw.saturating_sub(max_size_len + 1 + unconstrained_tree_width + 6);
            (unconstrained_tree_width, bw)
        } else {
            let bw = 4;
            let tw_tree = tw.saturating_sub(fixed_overhead + bw);
            (tw_tree, bw)
        }
    };

    let mut lines = Vec::new();

    for (i, node) in nodes.iter().enumerate() {
        let size_str = format!("{:>width$}", size_strs[i], width = max_size_len);

        let prefix_conn_len = node.prefix.chars().count() + node.connector.chars().count();
        let name = &node.name;

        let tree_col = if prefix_conn_len >= tree_width {
            let full = format!("{}{}", node.prefix, node.connector);
            full.chars().take(tree_width).collect::<String>()
        } else {
            let available_for_name = tree_width - prefix_conn_len;
            let name_chars = name.chars().count();
            let truncated_name = if name_chars <= available_for_name {
                name.clone()
            } else if available_for_name >= 3 {
                let take = available_for_name - 3;
                format!("{}...", name.chars().take(take).collect::<String>())
            } else {
                ".".repeat(available_for_name)
            };
            let formatted = format!("{}{}{}", node.prefix, node.connector, truncated_name);
            let formatted_len = formatted.chars().count();
            if formatted_len < tree_width {
                format!("{}{}", formatted, " ".repeat(tree_width - formatted_len))
            } else {
                formatted
            }
        };

        let bar_col = render_bar(&node.ancestor_sizes, root_size, bar_width, align_right);

        let pct = if root_size == 0 {
            0
        } else {
            ((node.size as f64 / root_size as f64) * 100.0).round() as u64
        };
        let pct_col = format!("{:>3}%", pct);

        lines.push(format!("{} {}│{}│{}", size_str, tree_col, bar_col, pct_col));
    }

    lines.join("\n") + "\n"
}

fn render_bar(ancestor_sizes: &[u64], root_size: u64, bar_width: usize, align_right: bool) -> String {
    if bar_width == 0 {
        return String::new();
    }

    let shades = ['█', '▓', '▒', '░'];
    let mut counts = Vec::new();

    for &sz in ancestor_sizes {
        let cnt = if root_size == 0 {
            0
        } else {
            ((sz as f64 / root_size as f64) * bar_width as f64).round() as usize
        }.min(bar_width);
        counts.push(cnt);
    }

    let mut segment_counts = Vec::new();
    let mut prev = 0;
    for &cnt in &counts {
        let inc = cnt.saturating_sub(prev);
        segment_counts.push(inc);
        prev = cnt.max(prev);
    }

    let mut bar_chars = Vec::new();
    let num_ancestors = ancestor_sizes.len();

    for (i, &cnt) in segment_counts.iter().enumerate() {
        if i + 1 == num_ancestors && num_ancestors > 1 {
            // Root extra size outside ancestor chain -> space
            break;
        }
        let shade = if i == 0 {
            shades[0]
        } else {
            shades[3]
        };
        for _ in 0..cnt {
            bar_chars.push(shade);
        }
    }

    while bar_chars.len() < bar_width {
        bar_chars.push(' ');
    }
    bar_chars.truncate(bar_width);

    if align_right {
        bar_chars.reverse();
    }

    bar_chars.into_iter().collect()
}
EOF"}

