        } else {
            if child_has_children { "├─┴" } else { "├──" }
        };

        let mut child_level_sibling = level_has_sibling_below.clone();
        child_level_sibling.push(!is_last);

        let mut prefix = String::new();
        for k in 0..depth {
            if k < level_has_sibling_below.len() && level_has_sibling_below[k] {
                prefix.push_str("│ ");
            } else {
                prefix.push_str("  ");
            }
        }
        if depth > 0 {
            prefix.push_str("  ");
        }

        let mut child_ancestors = vec![child.size];
        child_ancestors.extend(ancestor_sizes.iter().cloned());

        if child_has_children {
            flatten_bottom_up(
                child,
                depth + 1,
                child_level_sibling,
                prefix,
                connector,
                ancestor_sizes.clone(),
                out,
            );
        } else {
            out.push(FlattenedNode {
                name: child.name.clone(),
                size: child.size,
                prefix,
                connector,
                ancestor_sizes: child_ancestors,
            });
        }
    }

    out.push(FlattenedNode {
