        let is_first = i == 0;

        let child_has_children = !child.children.is_empty();

        let connector = if is_first {
            if child_has_children { "┌─┴" } else { "┌──" }
        } else {
            if child_has_children { "├─┴" } else { "├──" }
        };

        let child_depth = depth + 1;
        let mut child_ancestor_has_sibling = ancestor_has_sibling_below.clone();
        child_ancestor_has_sibling.push(!is_first);

