        for k in 0..child_depth {
            if k + 1 == child_depth {
                prefix.push_str("  ");
            } else if k < ancestor_has_sibling_below.len() && ancestor_has_sibling_below[k] {
                prefix.push_str("│ ");
            } else {
                prefix.push_str("  ");
            }
        }

        let mut child_ancestors = vec![child.size];
        child_ancestors.extend(ancestor_sizes.iter().cloned());

        if child_has_children {
