}

pub fn flatten_tree(
    tree: &DataTree,
    top_down: bool,
) -> Vec<FlattenedNode> {
    let mut nodes = Vec::new();
    let root_connector = if tree.children.is_empty() { "┌──" } else { "┌─┴" };
    flatten_bottom_up(tree, 0, Vec::new(), String::new(), root_connector, Vec::new(), &mut nodes);

    if top_down {
        nodes.reverse();
        for node in &mut nodes {
            node.connector = match node.connector {
                "┌─┴" => "└─┬",
                "├─┴" => "├─┬",
                "┌──" => "└──",
                "├──" => "├──",
                other => other,
            };
        }
    }

    nodes
}

fn flatten_top_down(
    tree: &DataTree,
    depth: usize,
    is_last_child: bool,
    parent_ancestors: Vec<u64>,
    out: &mut Vec<FlattenedNode>,
) {
    let mut ancestor_sizes = vec![tree.size];
    ancestor_sizes.extend(parent_ancestors.iter().cloned());

    let has_children = !tree.children.is_empty();
    let connector = if depth == 0 {
        if has_children { "└─┬" } else { "└──" }
    } else if has_children {
        if is_last_child { "└─┬" } else { "├─┬" }
    } else {
        if is_last_child { "└──" } else { "├──" }
    };

    let mut prefix = String::new();
    for _ in 0..depth.saturating_sub(1) {
        if is_last_child {
            prefix.push_str("  ");
        } else {
            prefix.push_str("│ ");
        }
    }

    out.push(FlattenedNode {
        name: tree.name.clone(),
        size: tree.size,
        prefix,
        connector,
        ancestor_sizes: ancestor_sizes.clone(),
    });

    let num_children = tree.children.len();
    for (i, child) in tree.children.iter().enumerate() {
        let child_is_last = i + 1 == num_children;
        flatten_top_down(
            child,
            depth + 1,
            child_is_last,
            ancestor_sizes.clone(),
            out,
        );
    }
}

fn flatten_bottom_up(
    tree: &DataTree,
    depth: usize,
    ancestor_is_not_first: Vec<bool>,
    own_prefix: String,
    own_connector: &'static str,
    parent_ancestors: Vec<u64>,
    out: &mut Vec<FlattenedNode>,
) {
    let mut ancestor_sizes = vec![tree.size];
    ancestor_sizes.extend(parent_ancestors.iter().cloned());

    let num_children = tree.children.len();

    for (i, child) in tree.children.iter().rev().enumerate() {
        let is_first = i == 0;

        let child_has_children = !child.children.is_empty();

        let child_connector = if is_first {
            if child_has_children { "┌─┴" } else { "┌──" }
        } else {
            if child_has_children { "├─┴" } else { "├──" }
        };

        let child_depth = depth + 1;
        let mut child_ancestor_is_not_first = ancestor_is_not_first.clone();
        child_ancestor_is_not_first.push(!is_first);

        let mut child_prefix = String::new();
        for k in 0..child_depth {
            if k == 0 {
                child_prefix.push_str("  ");
            } else if k - 1 < ancestor_is_not_first.len() && ancestor_is_not_first[k - 1] {
                child_prefix.push_str("│ ");
            } else {
                child_prefix.push_str("  ");
            }
        }

        let mut child_ancestors = vec![child.size];
        child_ancestors.extend(ancestor_sizes.iter().cloned());

        if child_has_children {
            flatten_bottom_up(
                child,
                child_depth,
                child_ancestor_is_not_first,
                child_prefix,
                child_connector,
                ancestor_sizes.clone(),
                out,
            );
        } else {
            out.push(FlattenedNode {
                name: child.name.clone(),
                size: child.size,
                prefix: child_prefix,
                connector: child_connector,
                ancestor_sizes: child_ancestors,
            });
        }
    }

    let _ = own_prefix;

    let mut prefix = String::new();
    for k in 0..depth {
        if k == 0 {
            prefix.push_str("  ");
        } else if k - 1 < ancestor_is_not_first.len() && ancestor_is_not_first[k - 1] {
            prefix.push_str("│ ");
        } else {
            prefix.push_str("  ");
        }
    }

    let connector = if depth == 0 {
        if tree.children.is_empty() { "┌──" } else { "┌─┴" }
    } else {
        own_connector
    };

    out.push(FlattenedNode {
        name: tree.name.clone(),
        size: tree.size,
        prefix,
        connector,
        ancestor_sizes,
    });
}

